// Constructor-style stub: allocate a fresh context and initialize it
SHA1_CTX *ctx = new SHA1_CTX();
// Initialize the context for a new computation
SHA1Init(ctx);
// Track context lifecycle state for downstream calls
FUZZ_SET_ATTR_INT(ctx, "sha1_init", 1);
FUZZ_SET_ATTR_INT(ctx, "sha1_padded", 0);
FUZZ_SET_ATTR_INT(ctx, "sha1_final", 0);
// Output: ctx persists in the object pool
// Validation: Ensures a new writable SHA1_CTX exists and is marked initialized; no API error path to handle.

// Enforce: ctx must have been initialized and not yet finalized
int inited = FUZZ_GET_ATTR_INT(ctx, "sha1_init");
int finalized = FUZZ_GET_ATTR_INT(ctx, "sha1_final");
if (!inited || finalized) { FUZZ_BAIL(); }
// Apply SHA-1 padding; caller promises no further Update after this unless reinit
SHA1Pad(ctx);
// Mark padded; keep initialized flag as-is
FUZZ_SET_ATTR_INT(ctx, "sha1_padded", 1);
// Output ctx back to pool; it remains valid for SHA1Final only (or reinit)
// Validation: Guards API order (Init -> Pad) and forbids use after Final; state updated for later checks.

// Enforce: ctx must be initialized, not finalized, and not padded (Update after Pad is forbidden)
int inited = FUZZ_GET_ATTR_INT(ctx, "sha1_init");
int padded = FUZZ_GET_ATTR_INT(ctx, "sha1_padded");
int finalized = FUZZ_GET_ATTR_INT(ctx, "sha1_final");
if (!inited || finalized || padded) { FUZZ_BAIL(); }

// Generate a data buffer; occasionally choose len==0 to cover no-op path
std::string data = FUZZ_PARAM_STR();
size_t max_len = data.size();
// Cap length to avoid excessive work and allow empty updates
unsigned int pick = *FUZZ_PARAM(unsigned int);
size_t len = (pick % 3 == 0) ? 0 : (max_len > 1024 ? 1024 : max_len);
// For len>0 data pointer must be non-null; for len==0, allow null to exercise no-op behavior
const uint8_t *ptr = (len > 0) ? reinterpret_cast<const uint8_t*>(data.data()) : nullptr;

// Feed the data into the hash computation
SHA1Update(ctx, ptr, len);

// State remains initialized; do not flip padded/finalized here
// Output ctx back to pool
// Validation: Respects pointer validity rules and sequencing; covers len==0 and len>0 paths.

// Enforce: ctx must be initialized and not already finalized
int inited = FUZZ_GET_ATTR_INT(ctx, "sha1_init");
int finalized = FUZZ_GET_ATTR_INT(ctx, "sha1_final");
if (!inited || finalized) { FUZZ_BAIL(); }

// Provide a 20-byte digest buffer as required
uint8_t digest[20];

// Finalize computation; implementation will perform any required padding
SHA1Final(digest, ctx);

// Mark the context as finalized and padded; further Update calls must bail until reinit
FUZZ_SET_ATTR_INT(ctx, "sha1_final", 1);
FUZZ_SET_ATTR_INT(ctx, "sha1_padded", 1);

// Return ctx to the pool to allow reinitialization via SHA1Init
// Validation: Ensures correct sequencing (Init/Update*/Pad? -> Final) and records state to prevent misuse afterwards.

// Prepare exact-size local buffers to satisfy alignment and non-null requirements
uint32_t state[5];
uint8_t block[64];

// Use FUZZ_PARAM with array types to get one random buffer each (avoid per-iteration macro calls)
const uint32_t (*rnd_state)[5] = FUZZ_PARAM(uint32_t[5]);
const uint8_t (*rnd_block)[64] = FUZZ_PARAM(uint8_t[64]);

// Copy fuzzed data into our writable, properly-aligned local arrays
for (int i = 0; i < 5; ++i) { state[i] = (*rnd_state)[i]; }
for (int i = 0; i < 64; ++i) { block[i] = (*rnd_block)[i]; }

// Process exactly one 64-byte block; fulfills: non-null, correct sizes, proper alignment
SHA1Transform(state, block);

// No persistent outputs; this exercises the low-level compressor paths
// Validation: Correctly sized arrays are provided and constraints (1 block, non-null) are enforced.

