import random
from typing import List

# This generator targets SHA1Update fuzzing, which accepts arbitrary binary data.
# Strategy: produce diverse, valid byte buffers exercising corner cases.

SHA1_BLOCK = 64
MAX_OUT = 4096

def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n


def _pattern_ff(n: int) -> bytes:
    return b"\xFF" * n


def _pattern_inc(n: int, start: int = 0) -> bytes:
    return bytes((start + i) & 0xFF for i in range(n))


def _pattern_dec(n: int, start: int = 255) -> bytes:
    return bytes((start - i) & 0xFF for i in range(n))


def _pattern_alt(n: int, a: int = 0x00, b: int = 0xFF) -> bytes:
    if n <= 0:
        return b""
    out = bytearray(n)
    for i in range(n):
        out[i] = a if (i & 1) == 0 else b
    return bytes(out)


def _pattern_ascii(n: int) -> bytes:
    base = (b"The quick brown fox jumps over the lazy dog. "
            b"Sphinx of black quartz, judge my vow! ")
    if n <= 0:
        return b""
    reps = (n + len(base) - 1) // len(base)
    return (base * reps)[:n]


def _pattern_random(n: int, rnd: random.Random) -> bytes:
    return rnd.randbytes(n)


def _pattern_repeated_motif(n: int, rnd: random.Random) -> bytes:
    motif_len = rnd.choice([1, 2, 3, 4, 5, 7, 8, 16, 32])
    motif = rnd.randbytes(motif_len)
    return (motif * ((n + motif_len - 1) // motif_len))[:n]


def _pattern_primes(n: int) -> bytes:
    # Simple sequence of primes modulo 256
    def gen_primes(limit: int) -> List[int]:
        sieve = [True] * (limit + 1)
        sieve[0:2] = [False, False]
        for p in range(2, int(limit ** 0.5) + 1):
            if sieve[p]:
                step = p
                start = p * p
                sieve[start: limit + 1: step] = [False] * (((limit - start) // step) + 1)
        return [i for i, v in enumerate(sieve) if v]
    primes = gen_primes(max(3000, n * 10))
    out = bytearray(n)
    for i in range(n):
        out[i] = primes[i % len(primes)] & 0xFF
    return bytes(out)


def _pattern_fib(n: int) -> bytes:
    out = bytearray(n)
    a, b = 1, 1
    for i in range(n):
        out[i] = a & 0xFF
        a, b = b, (a + b) & 0xFFFFFFFF
    return bytes(out)


def _safe_randint(rnd: random.Random, a: int, b: int) -> int:
    # Return a value in [a, b], clamping when a > b to single value a
    if a > b:
        return a
    return rnd.randint(a, b)


def _mix_chunks(target_len: int, rnd: random.Random) -> bytes:
    # Build buffer from chunks with sizes around block boundaries
    chunks: List[bytes] = []
    remaining = target_len
    while remaining > 0:
        # Prefer sizes that cross 64-byte boundaries
        max_small = min(remaining, 256)
        # Ensure the random range is valid even for small remaining
        size_candidates = [
            1 if remaining >= 1 else 0,
            2 if remaining >= 2 else 0,
            3 if remaining >= 3 else 0,
            min(remaining, SHA1_BLOCK - 1),
            min(remaining, SHA1_BLOCK),
            min(remaining, SHA1_BLOCK + 1),
            min(remaining, 2 * SHA1_BLOCK - 1),
            min(remaining, 2 * SHA1_BLOCK),
            min(remaining, 2 * SHA1_BLOCK + 1),
            _safe_randint(rnd, 1, max_small) if max_small >= 1 else 0,
        ]
        # Filter out zeros that may appear when remaining is small
        size_candidates = [s for s in size_candidates if s > 0]
        sz = rnd.choice(size_candidates)

        patt = rnd.randrange(8)
        if patt == 0:
            chunk = _pattern_zero(sz)
        elif patt == 1:
            chunk = _pattern_ff(sz)
        elif patt == 2:
            chunk = _pattern_inc(sz, rnd.randint(0, 255))
        elif patt == 3:
            chunk = _pattern_dec(sz, rnd.randint(0, 255))
        elif patt == 4:
            chunk = _pattern_alt(sz, rnd.randint(0, 255), rnd.randint(0, 255))
        elif patt == 5:
            chunk = _pattern_repeated_motif(sz, rnd)
        elif patt == 6:
            chunk = _pattern_ascii(sz)
        else:
            chunk = _pattern_random(sz, rnd)
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def _choose_lengths(rnd: random.Random) -> List[int]:
    candidates = [
        0, 1, 2, 3,
        SHA1_BLOCK - 1, SHA1_BLOCK, SHA1_BLOCK + 1,
        2 * SHA1_BLOCK - 1, 2 * SHA1_BLOCK, 2 * SHA1_BLOCK + 1,
        3 * SHA1_BLOCK - 1, 3 * SHA1_BLOCK, 3 * SHA1_BLOCK + 1,
        100, 255, 256, 511, 512, 1023, 1024,
        rnd.randint(5, 1500),
        rnd.randint(1501, 3500),
    ]
    length = rnd.choice([l for l in candidates if l <= MAX_OUT])
    return [length]


def _build_for_length(n: int, rnd: random.Random) -> bytes:
    mode = rnd.randrange(10)
    if n == 0:
        return b""
    if mode == 0:
        return _pattern_zero(n)
    if mode == 1:
        return _pattern_ff(n)
    if mode == 2:
        return _pattern_inc(n, rnd.randint(0, 255))
    if mode == 3:
        return _pattern_dec(n, rnd.randint(0, 255))
    if mode == 4:
        return _pattern_alt(n, rnd.randint(0, 255), rnd.randint(0, 255))
    if mode == 5:
        return _pattern_ascii(n)
    if mode == 6:
        return _pattern_primes(n)
    if mode == 7:
        return _pattern_fib(n)
    if mode == 8:
        return _pattern_repeated_motif(n, rnd)
    return _mix_chunks(n, rnd)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Occasionally produce empty to hit len==0 no-op path
    if rnd.random() < 0.12:
        return b""

    lengths = _choose_lengths(rnd)
    n = lengths[0]

    data = _build_for_length(n, rnd)

    # Ensure final size constraint
    if len(data) > MAX_OUT:
        data = data[:MAX_OUT]

    # Randomly prepend or append small offsets to cross block boundaries more
    tweak = rnd.random()
    if 0.2 < tweak < 0.3 and len(data) + 3 <= MAX_OUT:
        pad = _pattern_random(rnd.randint(1, 3), rnd)
        data = pad + data
    elif 0.3 <= tweak < 0.4 and len(data) + 3 <= MAX_OUT:
        pad = _pattern_random(rnd.randint(1, 3), rnd)
        data = data + pad

    return data
